-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function () 
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

hl.on("hyprland.start", function ()
    -- Status bar
    hl.exec_cmd("waybar")
    -- Notification daemon
    hl.exec_cmd("mako")
    -- Wallpaper (wrapper applies it over IPC; see script for why)
    hl.exec_cmd("$HOME/.config/hypr/scripts/wallpaper.sh")
    -- Idle management (dim / lock / dpms / suspend)
    hl.exec_cmd("hypridle")
    -- Polkit authentication agent (GUI password prompts)
    hl.exec_cmd("systemctl --user start hyprpolkitagent")
    -- Clipboard history
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
    -- Keep clipboard contents alive after the source app closes (if installed)
    hl.exec_cmd("command -v wl-clip-persist >/dev/null && wl-clip-persist --clipboard regular")
    -- On-screen display for volume/brightness keys (if installed)
    hl.exec_cmd("command -v swayosd-server >/dev/null && swayosd-server")
    -- Load hyprpm plugins, then re-read the config so plugin options apply.
    -- Without the second step the hyprbars block below is skipped at boot,
    -- because hl.plugin.hyprbars does not exist yet when the config is parsed.
    hl.exec_cmd("command -v hyprpm >/dev/null && hyprpm reload -n && hyprctl reload")
end)


