-- Silence notifications for as long as a screen share is running, so nothing
-- private pops into a call. The "silenced" notice is drawn by Hyprland itself
-- rather than mako, because mako is muted by then.
hl.on("screenshare.state", function(active, kind, name)
    if active then
        hl.dispatch(hl.dsp.exec_cmd("makoctl mode -a do-not-disturb"))
        hl.notification.create({
            text    = "Screen sharing - notifications silenced",
            timeout = 4000,
            icon    = "warning",
        })
    else
        hl.dispatch(hl.dsp.exec_cmd(
            "makoctl mode -r do-not-disturb && notify-send -u low 'Screen share ended' 'Notifications back on'"))
    end
end)


