-- Trackpad gestures (apple-spi-trackpad). 1:1 with the swipe, so they track
-- your fingers rather than firing once.
-- No workspace-overview plugin builds against 0.56.2 (hyprexpo was removed from
-- hyprwm/hyprland-plugins; Hyprspace still pins 0.50.1), so this is a picker
-- over every window on every workspace instead.
local function overview()
    hl.dispatch(hl.dsp.exec_cmd("$HOME/.config/hypr/scripts/windowswitcher.py"))
end

-- 3 fingers sideways: slide between workspaces
hl.gesture({ fingers = 3, direction = "horizontal", action = "workspace" })

-- 3 fingers up/down: fullscreen the window, or reach for the scratchpad
hl.gesture({ fingers = 3, direction = "up",   scale = 1.5, action = "fullscreen" })
hl.gesture({ fingers = 3, direction = "down", action = "special", workspace_name = "scratchpad" })

-- 4 fingers up: workspace overview (needs the hyprexpo plugin)
hl.gesture({ fingers = 4, direction = "up", action = overview })

-- 4-finger pinch: live cursor zoom, anchored where the pinch started.
-- Deliberately 4 fingers, so 2-finger pinch still reaches the browser.
hl.gesture({ fingers = 4, direction = "pinch", action = "cursor_zoom", zoom_level = 1, mode = "live" })

-- Example per-device config
-- See https://wiki.hypr.land/Configuring/Advanced-and-Cool/Devices/ for more
hl.device({
    name        = "epic-mouse-v1",
    sensitivity = -0.5,
})


