-- Omarchy's keymap (github.com/basecamp/omarchy), translated to the Lua config
-- and rewired to the tools actually installed here (no omarchy-* helpers).
-- Layout source: default/hypr/bindings/{tiling-v2,utilities,clipboard,media}.conf
--                config/hypr/bindings.conf

local mainMod  = "SUPER" -- Sets "Windows" key as main modifier
local browser  = "chromium"
local editor   = "kitty -e vim"
local webapp   = "chromium --app="

-- Digit row. Omarchy binds these by keycode (code:10-19) so the layout does not
-- matter; kb_layout here is "us", so the plain keysyms are equivalent and show
-- up properly in `hyprctl binds`.
local digitKeys = { "1", "2", "3", "4", "5", "6", "7", "8", "9", "0" }


-------------------
---- 1. APPS ------
-------------------

hl.bind(mainMod .. " + Return",               hl.dsp.exec_cmd(terminal),     { description = "Terminal" })
hl.bind(mainMod .. " + SHIFT + Return",       hl.dsp.exec_cmd(browser),      { description = "Browser" })
hl.bind(mainMod .. " + SHIFT + B",            hl.dsp.exec_cmd(browser),      { description = "Browser" })
hl.bind(mainMod .. " + SHIFT + ALT + B",      hl.dsp.exec_cmd(browser .. " --incognito"), { description = "Browser (private)" })
hl.bind(mainMod .. " + SHIFT + F",            hl.dsp.exec_cmd(fileManager),  { description = "File manager" })
hl.bind(mainMod .. " + SHIFT + N",            hl.dsp.exec_cmd(editor),       { description = "Editor" })
hl.bind(mainMod .. " + SHIFT + T",            hl.dsp.exec_cmd("kitty --class TUI.float -e sh -c 'command -v btop >/dev/null && btop || htop'"), { description = "Activity monitor" })

-- Web apps (Omarchy runs these as PWAs; chromium --app is the same idea)
hl.bind(mainMod .. " + SHIFT + A",            hl.dsp.exec_cmd(webapp .. "https://chatgpt.com"),        { description = "ChatGPT" })
hl.bind(mainMod .. " + SHIFT + ALT + A",      hl.dsp.exec_cmd(webapp .. "https://grok.com"),           { description = "Grok" })
hl.bind(mainMod .. " + SHIFT + Y",            hl.dsp.exec_cmd(webapp .. "https://youtube.com/"),       { description = "YouTube" })
hl.bind(mainMod .. " + SHIFT + X",            hl.dsp.exec_cmd(webapp .. "https://x.com/"),             { description = "X" })
hl.bind(mainMod .. " + SHIFT + ALT + X",      hl.dsp.exec_cmd(webapp .. "https://x.com/compose/post"), { description = "X post" })
hl.bind(mainMod .. " + SHIFT + ALT + G",      hl.dsp.exec_cmd(webapp .. "https://web.whatsapp.com/"),  { description = "WhatsApp" })
hl.bind(mainMod .. " + SHIFT + CTRL + G",     hl.dsp.exec_cmd(webapp .. "https://messages.google.com/web/conversations"), { description = "Google Messages" })
hl.bind(mainMod .. " + SHIFT + P",            hl.dsp.exec_cmd(webapp .. "https://photos.google.com/"), { description = "Google Photos" })

-- Omarchy also ships: SUPER SHIFT + M music, + O Obsidian, + G Signal, + D lazydocker,
-- + W Typora, + SLASH 1Password, + C/E HEY calendar & mail. Not installed here; add
-- them the same way once the app exists.


---------------------
---- 2. TILING ------
---------------------

hl.bind(mainMod .. " + W", hl.dsp.window.close(), { description = "Close window" })
-- Under a Lua config `hyprctl dispatch` expects Lua, so do this in-process.
hl.bind("CTRL + ALT + Delete", function()
    for _, w in ipairs(hl.get_windows()) do
        hl.dispatch(hl.dsp.window.close({ window = w }))
    end
end, { description = "Close all windows" })

hl.bind(mainMod .. " + J",         hl.dsp.layout("togglesplit"),                          { description = "Toggle window split" })
hl.bind(mainMod .. " + P",         hl.dsp.window.pseudo(),                                { description = "Pseudo window" })
hl.bind(mainMod .. " + T",         hl.dsp.window.float({ action = "toggle" }),            { description = "Toggle window floating/tiling" })
hl.bind(mainMod .. " + F",         hl.dsp.window.fullscreen({ mode = "fullscreen" }),     { description = "Full screen" })
hl.bind(mainMod .. " + CTRL + F",  hl.dsp.window.fullscreen_state({ internal = 0, client = 2 }), { description = "Tiled full screen" })
hl.bind(mainMod .. " + ALT + F",   hl.dsp.window.fullscreen({ mode = "maximized" }),      { description = "Full width" })

-- Pop a window out: float it and pin it above everything
hl.bind(mainMod .. " + O", function()
    hl.dispatch(hl.dsp.window.float({ action = "enable" }))
    hl.dispatch(hl.dsp.window.pin({ action = "enable" }))
    hl.dispatch(hl.dsp.window.bring_to_top())
end, { description = "Pop window out (float & pin)" })

-- Omarchy toggles the layout per workspace; this toggles it globally
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd(
    [[case "$(hyprctl getoption general:layout)" in *dwindle*) hyprctl keyword general:layout master;; *) hyprctl keyword general:layout dwindle;; esac]]),
    { description = "Toggle workspace layout" })

-- Move focus with SUPER + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }),  { description = "Focus on left window" })
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }), { description = "Focus on right window" })
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }),    { description = "Focus on above window" })
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }),  { description = "Focus on below window" })

-- Swap the active window with its neighbour
hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.swap({ direction = "left" }),  { description = "Swap window to the left" })
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.swap({ direction = "right" }), { description = "Swap window to the right" })
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.swap({ direction = "up" }),    { description = "Swap window up" })
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.swap({ direction = "down" }),  { description = "Swap window down" })

-- Move the whole workspace to another monitor
hl.bind(mainMod .. " + SHIFT + ALT + left",  hl.dsp.workspace.move({ monitor = "l" }), { description = "Move workspace to left monitor" })
hl.bind(mainMod .. " + SHIFT + ALT + right", hl.dsp.workspace.move({ monitor = "r" }), { description = "Move workspace to right monitor" })
hl.bind(mainMod .. " + SHIFT + ALT + up",    hl.dsp.workspace.move({ monitor = "u" }), { description = "Move workspace to up monitor" })
hl.bind(mainMod .. " + SHIFT + ALT + down",  hl.dsp.workspace.move({ monitor = "d" }), { description = "Move workspace to down monitor" })

-- Workspaces on the digit row: switch, move window, move window silently
for i, key in ipairs(digitKeys) do
    hl.bind(mainMod .. " + " .. key,
        hl.dsp.focus({ workspace = i }),
        { description = "Switch to workspace " .. i })
    hl.bind(mainMod .. " + SHIFT + " .. key,
        hl.dsp.window.move({ workspace = i }),
        { description = "Move window to workspace " .. i })
    hl.bind(mainMod .. " + SHIFT + ALT + " .. key,
        hl.dsp.window.move({ workspace = i, follow = false }),
        { description = "Move window silently to workspace " .. i })
end

-- Scratchpad
hl.bind(mainMod .. " + S",       hl.dsp.workspace.toggle_special("scratchpad"), { description = "Toggle scratchpad" })
hl.bind(mainMod .. " + ALT + S", hl.dsp.window.move({ workspace = "special:scratchpad", follow = false }), { description = "Move window to scratchpad" })

-- TAB between workspaces
hl.bind(mainMod .. " + Tab",           hl.dsp.focus({ workspace = "e+1" }),      { description = "Next workspace" })
hl.bind(mainMod .. " + SHIFT + Tab",   hl.dsp.focus({ workspace = "e-1" }),      { description = "Previous workspace" })
hl.bind(mainMod .. " + CTRL + Tab",    hl.dsp.focus({ workspace = "previous" }), { description = "Former workspace" })

-- Named project workspaces: jump to sub-workspace 1 of each project.
for _, proj in ipairs(projects) do
    local n = proj.name
    hl.bind(mainMod .. " + SHIFT + " .. proj.key,
        hl.dsp.focus({ workspace = "name:" .. n .. ".1" }),
        { description = n .. " workspace" })
end

-- Cycle sub-workspaces within the current project (no-op elsewhere).
hl.bind(mainMod .. " + bracketright", hl.dsp.exec_cmd(wsSub .. " next"), { description = "Next sub-workspace" })
hl.bind(mainMod .. " + bracketleft",  hl.dsp.exec_cmd(wsSub .. " prev"), { description = "Previous sub-workspace" })

-- Jump to whatever has been waiting longest: a pending question first, then a
-- finished command, oldest of each. Repeating it walks the backlog in order.
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd("$HOME/.local/bin/ws-attention"),
    { description = "Go to what needs me" })

-- Clickable F1-F12 overlay. This machine has a Touch Bar and no physical
-- function row; the overlay never takes keyboard focus, so the keys it
-- sends land in whatever window is actually focused. Re-run to dismiss.
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd("$HOME/.config/hypr/scripts/fkeys-overlay.py"), { description = "F-key overlay" })
-- The Touch Bar on screen. Where a real strip exists Fn belongs to it, so the
-- bar answers to a double-tap of Ctrl there and leaves Fn alone; elsewhere
-- there is no conflict and Fn is the trigger. dfrbar-launch decides which,
-- per machine, so this pair is correct everywhere.
-- The Ctrl bind is non-consuming: Ctrl keeps working as a modifier.
hl.bind("XF86Fn", hl.dsp.exec_cmd("$HOME/.config/hypr/scripts/dfrbar-launch fn"), { description = "On-screen Touch Bar (Fn)" })
hl.bind("Control_L", hl.dsp.exec_cmd("$HOME/.config/hypr/scripts/dfrbar-launch ctrl"), { description = "On-screen Touch Bar (double-tap Ctrl)", non_consuming = true })
hl.bind("Control_R", hl.dsp.exec_cmd("$HOME/.config/hypr/scripts/dfrbar-launch ctrl"), { description = "On-screen Touch Bar (double-tap Ctrl)", non_consuming = true })
-- Also sent by the Touch Bar's commit counter, so tapping the figures opens
-- the month behind them.
hl.bind(mainMod .. " + SHIFT + G", hl.dsp.exec_cmd("$HOME/.config/hypr/scripts/commitheat.py"), { description = "Commits by hour" })
-- Also sent by the Touch Bar's usage buttons, one combo per account, so
-- tapping a set of bars opens everything known about that account. Keep
-- these in step with the Account keys in tiny-dfr.config.toml.
local llmdetail = "$HOME/.config/hypr/scripts/llmdetail.py "
hl.bind(mainMod .. " + SHIFT + U", hl.dsp.exec_cmd(llmdetail .. "you@example.com"),   { description = "Usage: first account" })
hl.bind(mainMod .. " + SHIFT + I", hl.dsp.exec_cmd(llmdetail .. "other@example.com"), { description = "Usage: second account" })
hl.bind(mainMod .. " + SHIFT + M", hl.dsp.exec_cmd(llmdetail .. "codex"),             { description = "Usage: codex" })
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd(llmdetail .. "opencode-go"),      { description = "Usage: opencode-go" })

-- Cycle windows on the active workspace
hl.bind("ALT + Tab", function()
    hl.dispatch(hl.dsp.window.cycle_next())
    hl.dispatch(hl.dsp.window.bring_to_top())
end, { description = "Focus on next window" })
hl.bind("ALT + SHIFT + Tab", function()
    hl.dispatch(hl.dsp.window.cycle_next({ next = false }))
    hl.dispatch(hl.dsp.window.bring_to_top())
end, { description = "Focus on previous window" })

-- Cycle monitors
hl.bind("CTRL + ALT + Tab",         hl.dsp.focus({ monitor = "+1" }), { description = "Focus on next monitor" })
hl.bind("CTRL + ALT + SHIFT + Tab", hl.dsp.focus({ monitor = "-1" }), { description = "Focus on previous monitor" })

-- Resize the active window with SUPER + - / =
hl.bind(mainMod .. " + minus",           hl.dsp.window.resize({ x = -100, y = 0, relative = true }), { description = "Expand window left" })
hl.bind(mainMod .. " + equal",           hl.dsp.window.resize({ x = 100,  y = 0, relative = true }), { description = "Shrink window left" })
hl.bind(mainMod .. " + SHIFT + minus",   hl.dsp.window.resize({ x = 0, y = -100, relative = true }), { description = "Shrink window up" })
hl.bind(mainMod .. " + SHIFT + equal",   hl.dsp.window.resize({ x = 0, y = 100,  relative = true }), { description = "Expand window down" })

-- Scroll through workspaces, drag windows with the mouse
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }), { description = "Scroll active workspace forward" })
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }), { description = "Scroll active workspace backward" })
hl.bind(mainMod .. " + mouse:272",  hl.dsp.window.drag(),   { mouse = true, description = "Move window" })
hl.bind(mainMod .. " + mouse:273",  hl.dsp.window.resize(), { mouse = true, description = "Resize window" })


