--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})


------------------------------------------------
---- OMARCHY WINDOW RULES (default/hypr/*) ------
------------------------------------------------

-- Everything gets the default-opacity tag; the app rules below opt out of it,
-- and the very last rule applies the opacity to whatever still carries it.
hl.window_rule({ name = "tag-default-opacity", match = { class = ".*" }, tag = "+default-opacity" })

-- Terminals: Hyprland keeps them nearly opaque; the see-through part is
-- kitty's own background_opacity, which keeps the text crisp.
hl.window_rule({ name = "tag-terminal",  match = { class = "(Alacritty|kitty|com.mitchellh.ghostty|foot)" }, tag = "+terminal" })
hl.window_rule({ name = "terminal-untag", match = { tag = "terminal" }, tag = "-default-opacity" })
hl.window_rule({ name = "terminal-opacity", match = { tag = "terminal" }, opacity = "0.985 0.96" })

-- Browsers: only a hint of fade when unfocused
hl.window_rule({ name = "tag-chromium", match = { class = "((google-)?[cC]hrom(e|ium)|[bB]rave-browser|[mM]icrosoft-edge|Vivaldi-stable|helium)" }, tag = "+chromium-based-browser" })
hl.window_rule({ name = "tag-firefox",  match = { class = "([fF]irefox|zen|librewolf)" }, tag = "+firefox-based-browser" })
hl.window_rule({ name = "chromium-untag", match = { tag = "chromium-based-browser" }, tag = "-default-opacity" })
hl.window_rule({ name = "firefox-untag",  match = { tag = "firefox-based-browser" },  tag = "-default-opacity" })
-- Chromium --app windows misbehave unless forced to tile
hl.window_rule({ name = "chromium-tile",    match = { tag = "chromium-based-browser" }, tile = true })
hl.window_rule({ name = "chromium-opacity", match = { tag = "chromium-based-browser" }, opacity = "1.0 0.985" })
hl.window_rule({ name = "firefox-opacity",  match = { tag = "firefox-based-browser" },  opacity = "1.0 0.985" })
-- The "... is sharing your screen" bar has a broken Hide button on Wayland
hl.window_rule({ name = "hide-sharing-bar", match = { title = ".*is sharing.*" }, workspace = "special silent" })

-- Picture-in-picture: floating, pinned, bottom-right, no border, never faded
hl.window_rule({ name = "tag-pip",     match = { title = "(Picture.?in.?[Pp]icture)" }, tag = "+pip" })
hl.window_rule({ name = "pip-untag",   match = { tag = "pip" }, tag = "-default-opacity" })
hl.window_rule({ name = "pip-float",   match = { tag = "pip" }, float = true })
hl.window_rule({ name = "pip-pin",     match = { tag = "pip" }, pin = true })
hl.window_rule({ name = "pip-size",    match = { tag = "pip" }, size = "600 338" })
hl.window_rule({ name = "pip-aspect",  match = { tag = "pip" }, keep_aspect_ratio = true })
hl.window_rule({ name = "pip-border",  match = { tag = "pip" }, border_size = 0 })
hl.window_rule({ name = "pip-opacity", match = { tag = "pip" }, opacity = "1 1" })
hl.window_rule({ name = "pip-place",   match = { tag = "pip" }, move = "monitor_w-window_w-40 monitor_h*0.04" })

-- Utility windows that should float centred instead of tiling
hl.window_rule({ name = "tag-floating-window", match = { class = "(TUI.float|org.gnome.Calculator|org.gnome.Evince|com.gabm.satty|imv|mpv|blueman-manager|nm-connection-editor|org.pulseaudio.pavucontrol|pavucontrol)" }, tag = "+floating-window" })
hl.window_rule({ name = "floating-window-float",  match = { tag = "floating-window" }, float = true })
hl.window_rule({ name = "floating-window-center", match = { tag = "floating-window" }, center = true })
hl.window_rule({ name = "floating-window-size",   match = { tag = "floating-window" }, size = "875 600" })

-- File pickers and save dialogs
hl.window_rule({
    name  = "float-file-dialogs",
    match = {
        class = "(xdg-desktop-portal-gtk|sublime_text|DesktopEditors|org.gnome.Nautilus|org.kde.dolphin)",
        title = "^(Open.*Files?|Open [Ff]older.*|Save.*Files?|Save.*As|Save|All Files|.*wants to [open|save].*|[Cc]hoose.*)",
    },
    tag = "+floating-window",
})

-- Media windows stay fully opaque
hl.window_rule({ name = "media-untag",   match = { class = "^(zoom|vlc|mpv|org.kde.kdenlive|com.obsproject.Studio|imv)$" }, tag = "-default-opacity" })
hl.window_rule({ name = "media-opacity", match = { class = "^(zoom|vlc|mpv|org.kde.kdenlive|com.obsproject.Studio|imv)$" }, opacity = "1 1" })

-- Popped-out windows (SUPER + O) get softer corners
hl.window_rule({ name = "pop-rounding", match = { tag = "pop" }, rounding = 8 })

-- Applied last, to every window that did not opt out above
hl.window_rule({ name = "default-opacity", match = { tag = "default-opacity" }, opacity = "0.985 0.96" })

-- The launcher should not animate in
hl.layer_rule({ name = "no-anim-launcher", match = { namespace = "^hyprlauncher$" }, no_anim = true })


