-- hyprbars: title bars, styled to match the Catppuccin theme.
-- Guarded, because plugins must be rebuilt after every Hyprland update
-- (`hyprpm update`) and are simply absent until then.
if hl.plugin.hyprbars ~= nil then
    hl.config({
        plugin = {
            hyprbars = {
                bar_height        = 20,
                bar_color         = "rgba(1e1e2eee)",
                ["col.text"]      = "rgb(cdd6f4)",
                bar_text_font     = "JetBrainsMono Nerd Font",
                bar_text_size     = 10,
                bar_text_weight   = "medium",
                bar_text_align    = "left",
                bar_padding       = 10,
                bar_button_padding = 6,
                bar_buttons_alignment = "right",
                bar_blur          = true,
                bar_part_of_window = true,
                icon_on_hover     = true,
                inactive_button_color = "rgb(585b70)",
                on_double_click   = [[hyprctl dispatch 'hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" })']],
            },
        },
    })

    -- Buttons are laid out right to left from the aligned edge.
    hl.plugin.hyprbars.add_button({
        bg_color = "rgb(f38ba8)", fg_color = "rgb(1e1e2e)", size = 11, icon = "",
        action = "hyprctl dispatch 'hl.dsp.window.close()'",
    })
    hl.plugin.hyprbars.add_button({
        bg_color = "rgb(f9e2af)", fg_color = "rgb(1e1e2e)", size = 11, icon = "",
        action = [[hyprctl dispatch 'hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" })']],
    })
    hl.plugin.hyprbars.add_button({
        bg_color = "rgb(a6e3a1)", fg_color = "rgb(1e1e2e)", size = 11, icon = "",
        action = "hyprctl dispatch 'hl.dsp.window.float({ action = \"toggle\" })'",
    })

    -- Tiled windows keep every pixel: a 20px bar per window is a real cost in a
    -- tiling layout, and the groupbar already labels grouped windows.
    -- Delete this rule to get bars on everything.
    hl.window_rule({
        name  = "no-bar-on-tiled",
        match = { float = false },
        ["hyprbars:no_bar"] = true,
    })
end

